import java.lang.annotation.*;import java.lang.reflect.*;@Retention(RetentionPolicy.RUNTIME)@Target(ElementType.METHOD)@interface Run{}class SampleTests{@Run void first(){System.out.println("first passed");}@Run void second(){System.out.println("second passed");}void ignored(){}}public class MiniTestRunner{public static void main(String[]x)throws Exception{Object o=new SampleTests();int n=0;for(Method m:o.getClass().getDeclaredMethods())if(m.isAnnotationPresent(Run.class)){m.invoke(o);n++;}System.out.println("Ran: "+n);}}
